const LdpcBlock* ldpcBlocks(Rate r, int& count, int& blockRows) {
    switch (r) {
    case Rate::R04: count = (int)(sizeof kLdpc04 / sizeof kLdpc04[0]); blockRows = 35; return kLdpc04;
    case Rate::R06: count = (int)(sizeof kLdpc06 / sizeof kLdpc06[0]); blockRows = 23; return kLdpc06;
    default: count = (int)(sizeof kLdpc08 / sizeof kLdpc08[0]); blockRows = 11; return kLdpc08;
    }
}

